SELECT COUNT(DISTINCT order_id) AS orders_placed_in_2025
FROM v_sales
WHERE year = 2025;

SELECT COUNT(DISTINCT sku) AS distinct_skus_sold
FROM v_sales
WHERE year = 2023;

SELECT AVG(discount_pct) AS average_discount_percentage
FROM v_sales
WHERE year = 2024;

SELECT COUNT(*) AS order_lines_with_15_percent_discount
FROM v_sales
WHERE discount_pct = 15;

SELECT COUNT(*) AS suppliers_outside_us
FROM suppliers
WHERE country <> 'United States';
